// ---- lincomb.py: lazily reduced FpExt linear combinations ----
struct RkW { uint32_t lo[4]; uint32_t hi[4]; };   // S_j = hi*2^32 + lo, hi < P between steps
__device__ __forceinline__ static uint32_t rkw_mulhi(uint32_t a, uint32_t b) { return uint32_t((uint64_t(a) * uint64_t(b)) >> 32); }
__device__ __forceinline__ static uint32_t rkw_fold(uint32_t h) { uint32_t f = h - Fp::P; return h < f ? h : f; }
__device__ __forceinline__ static void rkw_mac(RkW& w, int j, uint32_t x, uint32_t y) {
#ifdef EF_WIDE
  uint64_t t = ((uint64_t(w.hi[j]) << 32) | w.lo[j]) + uint64_t(x) * uint64_t(y);
  EF_OPQ64(t);
  w.lo[j] = uint32_t(t); w.hi[j] = uint32_t(t >> 32);
#else
  uint32_t p = x * y, n = w.lo[j] + p;
  w.hi[j] = w.hi[j] + rkw_mulhi(x, y) + (n < p ? 1u : 0u);
  w.lo[j] = n;
#endif
}
// w = a*b (exact 64-bit dot products, NBETA folded into b), hi folded below P
__device__ __forceinline__ static RkW rkw_ee(FpExt a, FpExt b) {
  const uint32_t a0 = a.elems[0].asRaw(), a1 = a.elems[1].asRaw(), a2 = a.elems[2].asRaw(), a3 = a.elems[3].asRaw();
  const uint32_t b0 = b.elems[0].asRaw(), b1 = b.elems[1].asRaw(), b2 = b.elems[2].asRaw(), b3 = b.elems[3].asRaw();
  const uint32_t b1n = (b.elems[1] * Fp(Fp::P - 11)).asRaw();
  const uint32_t b2n = (b.elems[2] * Fp(Fp::P - 11)).asRaw();
  const uint32_t b3n = (b.elems[3] * Fp(Fp::P - 11)).asRaw();
  RkW w;
  const uint32_t X[4][4] = {{b0, b3n, b2n, b1n}, {b1, b0, b3n, b2n}, {b2, b1, b0, b3n}, {b3, b2, b1, b0}};
  for (int j = 0; j < 4; j++) {
    w.lo[j] = a0 * X[j][0]; w.hi[j] = rkw_mulhi(a0, X[j][0]);
    rkw_mac(w, j, a1, X[j][1]); rkw_mac(w, j, a2, X[j][2]); rkw_mac(w, j, a3, X[j][3]);
    w.hi[j] = rkw_fold(w.hi[j]);
  }
  return w;
}
// w += (neg ? -1 : 1) * a*b  (fold after every 2 products: hi < P + 2*(0.47P+1) < 2^32)
__device__ __forceinline__ static void rkw_ee_acc(RkW& w, FpExt a, FpExt b, bool neg) {
  uint32_t a0 = a.elems[0].asRaw(), a1 = a.elems[1].asRaw(), a2 = a.elems[2].asRaw(), a3 = a.elems[3].asRaw();
  if (neg) { a0 = Fp::P - a0; a1 = Fp::P - a1; a2 = Fp::P - a2; a3 = Fp::P - a3; }
  const uint32_t b0 = b.elems[0].asRaw(), b1 = b.elems[1].asRaw(), b2 = b.elems[2].asRaw(), b3 = b.elems[3].asRaw();
  const uint32_t b1n = (b.elems[1] * Fp(Fp::P - 11)).asRaw();
  const uint32_t b2n = (b.elems[2] * Fp(Fp::P - 11)).asRaw();
  const uint32_t b3n = (b.elems[3] * Fp(Fp::P - 11)).asRaw();
  const uint32_t X[4][4] = {{b0, b3n, b2n, b1n}, {b1, b0, b3n, b2n}, {b2, b1, b0, b3n}, {b3, b2, b1, b0}};
  for (int j = 0; j < 4; j++) {
    rkw_mac(w, j, a0, X[j][0]); rkw_mac(w, j, a1, X[j][1]); w.hi[j] = rkw_fold(w.hi[j]);
    rkw_mac(w, j, a2, X[j][2]); rkw_mac(w, j, a3, X[j][3]); w.hi[j] = rkw_fold(w.hi[j]);
  }
}
// w = (neg ? -f : f) * e  (initial term)
__device__ __forceinline__ static RkW rkw_ef0(Fp f, FpExt e, bool neg) {
  const uint32_t fr = neg ? Fp::P - f.asRaw() : f.asRaw();
  RkW w;
  for (int j = 0; j < 4; j++) { const uint32_t x = e.elems[j].asRaw(); w.lo[j] = fr * x; w.hi[j] = rkw_mulhi(fr, x); }
  return w;
}
// w += (neg ? -f : f) * e
__device__ __forceinline__ static void rkw_ef(RkW& w, Fp f, FpExt e, bool neg) {
  const uint32_t fr = neg ? Fp::P - f.asRaw() : f.asRaw();
  for (int j = 0; j < 4; j++) { rkw_mac(w, j, fr, e.elems[j].asRaw()); w.hi[j] = rkw_fold(w.hi[j]); }
}
// w += (neg ? -v : v)   (v*R as a product-domain value: hi += v)
__device__ __forceinline__ static void rkw_v(RkW& w, FpExt v, bool neg) {
  for (int j = 0; j < 4; j++) { const uint32_t r = v.elems[j].asRaw(); w.hi[j] = rkw_fold(w.hi[j] + (neg ? Fp::P - r : r)); }
}
__device__ __forceinline__ static FpExt rkw_fin(const RkW& w) {
  uint32_t r[4];
  for (int j = 0; j < 4; j++) { uint32_t t = w.hi[j] - rkw_mulhi(Fp::mulM(w.lo[j]), Fp::P); uint32_t u = t + Fp::P; r[j] = t < u ? t : u; }
  return FpExt(Fp::fromRaw(r[0]), Fp::fromRaw(r[1]), Fp::fromRaw(r[2]), Fp::fromRaw(r[3]));
}

// ---- lincombF: lazily reduced Fp linear combinations ----
struct RkW1 { uint32_t lo; uint32_t hi; };
__device__ __forceinline__ static uint32_t rkw1_mulhi(uint32_t a, uint32_t b) { return uint32_t((uint64_t(a) * uint64_t(b)) >> 32); }
__device__ __forceinline__ static uint32_t rkw1_fold(uint32_t h) { uint32_t f = h - Fp::P; return h < f ? h : f; }
__device__ __forceinline__ static RkW1 rkw1_ff0(Fp a, Fp b, bool neg) {
  const uint32_t x = neg ? Fp::P - a.asRaw() : a.asRaw(), y = b.asRaw();
  RkW1 w; w.lo = x * y; w.hi = rkw1_mulhi(x, y); return w;
}
__device__ __forceinline__ static void rkw1_ff(RkW1& w, Fp a, Fp b, bool neg) {
#ifdef EF_WIDE
  const uint32_t x = neg ? Fp::P - a.asRaw() : a.asRaw(), y = b.asRaw();
  uint64_t t = ((uint64_t(w.hi) << 32) | w.lo) + uint64_t(x) * uint64_t(y);
  EF_OPQ64(t);
  w.hi = rkw1_fold(uint32_t(t >> 32)); w.lo = uint32_t(t);
#else
  const uint32_t x = neg ? Fp::P - a.asRaw() : a.asRaw(), y = b.asRaw();
  uint32_t p = x * y, n = w.lo + p;
  w.hi = rkw1_fold(w.hi + rkw1_mulhi(x, y) + (n < p ? 1u : 0u));   // hi < P invariant: < 1.47P+1 before the fold
  w.lo = n;
#endif
}
__device__ __forceinline__ static void rkw1_v(RkW1& w, Fp v, bool neg) {
  const uint32_t r = v.asRaw(); w.hi = rkw1_fold(w.hi + (neg ? Fp::P - r : r));
}
__device__ __forceinline__ static Fp rkw1_fin(const RkW1& w) {
  const uint32_t h = w.hi;
  uint32_t t = h - rkw1_mulhi(Fp::mulM(w.lo), Fp::P); uint32_t u = t + Fp::P; return Fp::fromRaw(t < u ? t : u);
}
// ---- lazy poly_mix accumulator (RK_LAZYCHAIN) ----
struct RkAcc { uint32_t lo[4]; uint32_t hi[4]; };   // S_j = hi*2^32+lo, invariant hi < P
__device__ __forceinline__ static uint32_t rk_mulhi(uint32_t a, uint32_t b) { return uint32_t((uint64_t(a) * uint64_t(b)) >> 32); }
__device__ __forceinline__ static uint32_t rk_umin(uint32_t a, uint32_t b) { return a < b ? a : b; }
__device__ __forceinline__ static RkAcc rk_acc(FpExt b) { RkAcc s; for (int j = 0; j < 4; j++) { s.lo[j] = 0; s.hi[j] = b.elems[j].asRaw(); } return s; }
__device__ __forceinline__ static RkAcc rk_acc(const RkAcc& s) { return s; }
template <typename A> __device__ __forceinline__ static RkAcc rk_link(const A& base, Fp c, const FpExt& pm) {
#ifdef EF_WIDE
  RkAcc s = rk_acc(base); uint32_t cr = c.asRaw();
  for (int j = 0; j < 4; j++) {
    uint64_t t = ((uint64_t(s.hi[j]) << 32) | s.lo[j]) + uint64_t(cr) * uint64_t(pm.elems[j].asRaw());
    EF_OPQ64(t);
    uint32_t h = uint32_t(t >> 32);
    s.lo[j] = uint32_t(t); s.hi[j] = rk_umin(h, h - Fp::P);
  }
  return s;
#else
  RkAcc s = rk_acc(base); uint32_t cr = c.asRaw();
  for (int j = 0; j < 4; j++) {
    uint32_t p = pm.elems[j].asRaw();
    uint32_t pl = cr * p, ph = rk_mulhi(cr, p);
    uint32_t n = s.lo[j] + pl;
    uint32_t h = s.hi[j] + ph + (n < pl ? 1u : 0u);   // < P + 0.47P + 1 < 2P
    s.lo[j] = n; s.hi[j] = rk_umin(h, h - Fp::P);
  }
  return s;
#endif
}
template <typename A> __device__ __forceinline__ static RkAcc rk_link(const A& base, FpExt c, const FpExt& pm) {
  RkAcc s = rk_acc(base); FpExt p = c * pm;
  for (int j = 0; j < 4; j++) { uint32_t h0 = rk_umin(s.hi[j], s.hi[j] - Fp::P); uint32_t h = h0 + p.elems[j].asRaw(); s.hi[j] = rk_umin(h, h - Fp::P); }
  return s;
}
// no-fold variant: input hi < P, output hi < P + 0.47P + 1 < 2P (fits u32); the next link must fold.
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf(const A& base, Fp c, const FpExt& pm) {
#ifdef EF_WIDE
  RkAcc s = rk_acc(base); uint32_t cr = c.asRaw();
  for (int j = 0; j < 4; j++) {
    uint64_t t = ((uint64_t(s.hi[j]) << 32) | s.lo[j]) + uint64_t(cr) * uint64_t(pm.elems[j].asRaw());
    EF_OPQ64(t);
    s.lo[j] = uint32_t(t); s.hi[j] = uint32_t(t >> 32);
  }
  return s;
#else
  RkAcc s = rk_acc(base); uint32_t cr = c.asRaw();
  for (int j = 0; j < 4; j++) {
    uint32_t p = pm.elems[j].asRaw();
    uint32_t pl = cr * p, ph = rk_mulhi(cr, p);
    uint32_t n = s.lo[j] + pl;
    s.hi[j] = s.hi[j] + ph + (n < pl ? 1u : 0u);
    s.lo[j] = n;
  }
  return s;
#endif
}
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf(const A& base, FpExt c, const FpExt& pm) {
  return rk_link(base, c, pm);
}
__device__ __forceinline__ static FpExt rk_fin(const RkAcc& s) {
  uint32_t r[4];
  for (int j = 0; j < 4; j++) {
    uint32_t m = Fp::mulM(s.lo[j]);
    uint32_t t = s.hi[j] - rk_mulhi(m, Fp::P);
    r[j] = rk_umin(t, t + Fp::P);
  }
  return FpExt(Fp::fromRaw(r[0]), Fp::fromRaw(r[1]), Fp::fromRaw(r[2]), Fp::fromRaw(r[3]));
}


// ---- lazyfp.py: lazy [0, 2P) Fp results (see evalfast/lazyfp.py for the bounds) ----
__device__ __forceinline__ static ::risc0::Fp ef_ladd(::risc0::Fp a, ::risc0::Fp b) { return ::risc0::Fp::fromRaw(a.asRaw() + b.asRaw()); }
__device__ __forceinline__ static ::risc0::Fp ef_lsub(::risc0::Fp a, ::risc0::Fp b) { return ::risc0::Fp::fromRaw(a.asRaw() + (::risc0::Fp::P - b.asRaw())); }
__device__ __forceinline__ static ::risc0::Fp ef_lmul(::risc0::Fp a, ::risc0::Fp b) {
  const uint32_t x = a.asRaw(), y = b.asRaw(); const uint32_t lo = x * y; const uint32_t hi = uint32_t((uint64_t(x) * uint64_t(y)) >> 32);
  const uint32_t m = ::risc0::Fp::mulM(lo); return ::risc0::Fp::fromRaw(hi - uint32_t((uint64_t(m) * uint64_t(::risc0::Fp::P)) >> 32) + ::risc0::Fp::P);
}

// ---- close.py: lazy closures B + u * PM_k with a precomputed NBETA-folded constant table ----
__device__ __forceinline__ static uint64_t ef_madw(uint32_t a, uint32_t b, uint64_t c) {
#ifdef EF_MADW_ASM
  uint64_t d; asm("mad.wide.u32 %0, %1, %2, %3;" : "=l"(d) : "r"(a), "r"(b), "l"(c)); return d;
#else
  uint64_t d = c + uint64_t(a) * uint64_t(b);
  EF_OPQ64(d);
  return d;
#endif
}
__device__ __forceinline__ static uint64_t ef_fold64(uint64_t t) {
  uint32_t h = uint32_t(t >> 32), f = h - Fp::P; h = h < f ? h : f;
  return (uint64_t(h) << 32) | uint32_t(t);
}
// pm row j of the NBETA-folded 4x4 matrix of constant k
#define EF_PMROW(b, n) const uint32_t X[4][4] = {{b.x, n.z, n.y, n.x}, {b.y, b.x, n.z, n.y}, {b.z, b.y, b.x, n.z}, {b.w, b.z, b.y, b.x}}
__device__ __forceinline__ static void rk_cl_acc(RkW& w, const FpExt& u, uint32_t k) {
  const uint32_t a0 = u.elems[0].asRaw(), a1 = u.elems[1].asRaw(), a2 = u.elems[2].asRaw(), a3 = u.elems[3].asRaw();
  const uint4 b = reinterpret_cast<const uint4*>(ef_pm_raw)[k], n = reinterpret_cast<const uint4*>(ef_pmn_raw)[k];
  EF_PMROW(b, n);
  for (int j = 0; j < 4; j++) {
    uint64_t t = (uint64_t(w.hi[j]) << 32) | w.lo[j];
    t = ef_fold64(ef_madw(a1, X[j][1], ef_madw(a0, X[j][0], t)));
    t = ef_fold64(ef_madw(a3, X[j][3], ef_madw(a2, X[j][2], t)));
    w.lo[j] = uint32_t(t); w.hi[j] = uint32_t(t >> 32);
  }
}
__device__ __forceinline__ static RkW rk_cl0(const FpExt& b, const FpExt& u, uint32_t k) {
  RkW w; for (int j = 0; j < 4; j++) { w.lo[j] = 0; w.hi[j] = b.elems[j].asRaw(); }
  rk_cl_acc(w, u, k); return w;
}

// ---- linkext.py: rk_link with an FpExt term, products accumulated lazily ----
template <typename A> __device__ __forceinline__ static RkAcc rk_link_k(const A& base, Fp c, uint32_t k) { return rk_link(base, c, EF_PM(k)); }
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf_k(const A& base, Fp c, uint32_t k) { return rk_link_nf(base, c, EF_PM(k)); }
template <typename A> __device__ __forceinline__ static RkAcc rk_link_k(const A& base, FpExt c, uint32_t k) {
  RkAcc s = rk_acc(base);
  const uint32_t a0 = c.elems[0].asRaw(), a1 = c.elems[1].asRaw(), a2 = c.elems[2].asRaw(), a3 = c.elems[3].asRaw();
  const uint4 b = reinterpret_cast<const uint4*>(ef_pm_raw)[k], n = reinterpret_cast<const uint4*>(ef_pmn_raw)[k];
  EF_PMROW(b, n);
  for (int j = 0; j < 4; j++) {
    uint64_t t = ef_fold64((uint64_t(s.hi[j]) << 32) | s.lo[j]);
    t = ef_fold64(ef_madw(a1, X[j][1], ef_madw(a0, X[j][0], t)));
    t = ef_fold64(ef_madw(a3, X[j][3], ef_madw(a2, X[j][2], t)));
    s.lo[j] = uint32_t(t); s.hi[j] = uint32_t(t >> 32);
  }
  return s;
}
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf_k(const A& base, FpExt c, uint32_t k) { return rk_link_k(base, c, k); }
// ---- algebraic rewrite helpers (ec-algebra) ----
__device__ __forceinline__ static FpExt rk_xmul(const FpExt& a) {
  return FpExt(a.elems[3] * Fp(0x78000001u - 11u), a.elems[0], a.elems[1], a.elems[2]);
}
// pmlag_hip.py: on gfx11 and gfx12 each scalar chain link's constant loaded at most W links ahead,
// each FpExt-term link's and chained closure's constant rows not before the accumulator they depend on.
#if defined(__HIP_DEVICE_COMPILE__) && (defined(__GFX11__) || defined(__GFX12__))
#define EF_DEP(e) (e)
__device__ __forceinline__ static ::risc0::FpExt ef_pml(uint32_t k, uint32_t dep) {
  uint64_t p = reinterpret_cast<uint64_t>(ef_pm_raw);
  asm("" : "+s"(p) : "v"(dep));
  const uint4 v = ((const __attribute__((address_space(4))) uint4*)p)[k];
  return ::risc0::FpExt(::risc0::Fp::fromRaw(v.x), ::risc0::Fp::fromRaw(v.y), ::risc0::Fp::fromRaw(v.z), ::risc0::Fp::fromRaw(v.w));
}
__device__ __forceinline__ static uint4 ef_pmu(const uint32_t* tab, uint32_t k, uint32_t dep) {
  uint64_t p = reinterpret_cast<uint64_t>(tab);
  asm("" : "+s"(p) : "v"(dep));
  return ((const __attribute__((address_space(4))) uint4*)p)[k];
}
template <typename A> __device__ __forceinline__ static RkAcc rk_link_kl(const A& base, Fp c, uint32_t k, uint32_t dep) { return rk_link(base, c, ef_pml(k, dep)); }
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf_kl(const A& base, Fp c, uint32_t k, uint32_t dep) { return rk_link_nf(base, c, ef_pml(k, dep)); }
#else
#define EF_DEP(e) 0u
__device__ __forceinline__ static uint4 ef_pmu(const uint32_t* tab, uint32_t k, uint32_t) { return reinterpret_cast<const uint4*>(tab)[k]; }
template <typename A> __device__ __forceinline__ static RkAcc rk_link_kl(const A& base, Fp c, uint32_t k, uint32_t) { return rk_link_k(base, c, k); }
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf_kl(const A& base, Fp c, uint32_t k, uint32_t) { return rk_link_nf_k(base, c, k); }
#endif
// rk_link_k(base, FpExt c, k) and rk_cl_acc(w, u, k) with the constant rows through ef_pmu
template <typename A> __device__ __forceinline__ static RkAcc rk_link_kxl(const A& base, FpExt c, uint32_t k, uint32_t dep) {
  RkAcc s = rk_acc(base);
  const uint32_t a0 = c.elems[0].asRaw(), a1 = c.elems[1].asRaw(), a2 = c.elems[2].asRaw(), a3 = c.elems[3].asRaw();
  const uint4 b = ef_pmu(ef_pm_raw, k, dep), n = ef_pmu(ef_pmn_raw, k, dep);
  EF_PMROW(b, n);
  for (int j = 0; j < 4; j++) {
    uint64_t t = ef_fold64((uint64_t(s.hi[j]) << 32) | s.lo[j]);
    t = ef_fold64(ef_madw(a1, X[j][1], ef_madw(a0, X[j][0], t)));
    t = ef_fold64(ef_madw(a3, X[j][3], ef_madw(a2, X[j][2], t)));
    s.lo[j] = uint32_t(t); s.hi[j] = uint32_t(t >> 32);
  }
  return s;
}
__device__ __forceinline__ static void rk_cl_accl(RkW& w, const FpExt& u, uint32_t k, uint32_t dep) {
  const uint32_t a0 = u.elems[0].asRaw(), a1 = u.elems[1].asRaw(), a2 = u.elems[2].asRaw(), a3 = u.elems[3].asRaw();
  const uint4 b = ef_pmu(ef_pm_raw, k, dep), n = ef_pmu(ef_pmn_raw, k, dep);
  EF_PMROW(b, n);
  for (int j = 0; j < 4; j++) {
    uint64_t t = (uint64_t(w.hi[j]) << 32) | w.lo[j];
    t = ef_fold64(ef_madw(a1, X[j][1], ef_madw(a0, X[j][0], t)));
    t = ef_fold64(ef_madw(a3, X[j][3], ef_madw(a2, X[j][2], t)));
    w.lo[j] = uint32_t(t); w.hi[j] = uint32_t(t >> 32);
  }
}
template <typename A> __device__ __forceinline__ static RkAcc rk_link_kl(const A& base, FpExt c, uint32_t k, uint32_t dep) { return rk_link_kxl(base, c, k, dep); }
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf_kl(const A& base, FpExt c, uint32_t k, uint32_t dep) { return rk_link_kxl(base, c, k, dep); }
// ---- wmma_hip.py: poly_mix chains on the gfx12 matrix units (V_WMMA_I32_16X16X16_IU8) ----
#if defined(__HIP_DEVICE_COMPILE__) && (defined(__gfx1200__) || defined(__gfx1201__)) && !defined(EF_NO_WMMA)
#define EF_WM 1
#endif
#define EF_WUNP(...) __VA_ARGS__
#ifdef EF_WM
#define EF_W(w, ...) EF_WUNP w
#else
#define EF_W(w, ...) __VA_ARGS__
#endif
#ifdef EF_WM
typedef int ef_v4i __attribute__((ext_vector_type(4)));
typedef __attribute__((address_space(3))) uint32_t ef_lu32;
typedef const __attribute__((address_space(1))) uint32_t ef_wgu32;
#if defined(__GFX12__) // archsel_hip
#define EF_WSLOTS 12u  // staging slots per wave (1 regions of 12)
#else // archsel_hip
#define EF_WSLOTS 24u  // staging slots per wave (1 regions of 24)
#endif // archsel_hip
#define EF_WSTR 80u    // dwords per slot: 64 points + 16 pad, so the tile reads are bank-conflict free
__shared__ uint32_t ef_wlds[(EF_THREADS / 64) * EF_WSLOTS * EF_WSTR];
// lane, its wave's staging tile, rdo = (lane / 16) * EF_WSTR + lane % 16 (operand row group = link)
struct EfW { ef_lu32* st; ef_wgu32* q; uint32_t lane, rdo; };
__device__ __forceinline__ static EfW ef_wsetup() {
  EfW w;
  w.lane = threadIdx.x & 63u;
  w.rdo = (w.lane >> 4) * EF_WSTR + (w.lane & 15u);
  w.st = (ef_lu32*)(ef_wlds + (threadIdx.x >> 6) * (EF_WSLOTS * EF_WSTR));
  // The A operand table through an opaque SGPR base (an empty asm): each ef_wq load is then base +
  // lane offset + an immediate offset, instead of a 64-bit PC-relative SGPR address per constant
  // that the scheduler hoisted and spilled to VGPR lanes (~600 s_getpc and ~970 v_readlane per wave).
  uint64_t q = reinterpret_cast<uint64_t>(ef_wq_raw);
  asm("" : "+s"(q));
  w.q = (ef_wgu32*)q;
  return w;
}
#define EF_WSETUP const EfW efw = ef_wsetup();
__device__ __forceinline__ static void ef_wst(const EfW& w, uint32_t slot, Fp c) { w.st[slot * EF_WSTR + w.lane] = c.asRaw(); }
// A operand: Q rows of the links with constants k0..k0+3, or ka..kd with n < 4 real links (zero rows)
__device__ __forceinline__ static int ef_wq(const EfW& w, uint32_t k0) { return (int)(w.q + k0 * 16u)[w.lane]; }
__device__ __forceinline__ static int ef_wq4(const EfW& w, uint32_t ka, uint32_t kb, uint32_t kc, uint32_t kd, uint32_t n) {
  const uint32_t g = w.lane >> 4, k = g == 0 ? ka : g == 1 ? kb : g == 2 ? kc : kd;
  const int v = (int)w.q[k * 16u + (w.lane & 15u)];
  return g < n ? v : 0;
}
// 4 links (slots s0..s0+3) x 4 point tiles: unsigned bytes, i32 accumulation
__device__ __forceinline__ static void ef_wblk(const EfW& w, ef_v4i* d, uint32_t s0, int a) {
#pragma unroll
  for (int t = 0; t < 4; t++)
    d[t] = __builtin_amdgcn_wmma_i32_16x16x16_iu8_w64_gfx12(false, a, false, (int)w.st[s0 * EF_WSTR + w.rdo + 16u * t], d[t], false);
}
// Flush: lane (G = lane / 16, r) holds d[t] = (b = 0..3) of component G, point 16t + r: T = sum_b d_b << 8b
// (< 2^48), REDC (T_hi < P), back to point-per-lane through slots s0..s0+3, + base (canonical).
__device__ __forceinline__ static FpExt ef_wfin(const EfW& w, const ef_v4i* d, uint32_t s0, const FpExt& base) {
#pragma unroll
  for (int t = 0; t < 4; t++) {
    const uint32_t d0 = d[t][0], d1 = d[t][1], d2 = d[t][2], d3 = d[t][3];
    const uint32_t x = d0 + (d1 << 8), y = d2 + (d3 << 8);
    const uint32_t lo = x + (y << 16), hi = (y >> 16) + (lo < x ? 1u : 0u);
    const uint32_t m = Fp::mulM(lo), tt = hi - rk_mulhi(m, Fp::P);
    w.st[s0 * EF_WSTR + w.rdo + 16u * t] = rk_umin(tt, tt + Fp::P);
  }
  uint32_t r[4];
#pragma unroll
  for (int j = 0; j < 4; j++) { const uint32_t v = base.elems[j].asRaw() + w.st[(s0 + j) * EF_WSTR + w.lane]; r[j] = rk_umin(v, v - Fp::P); }
  return FpExt(Fp::fromRaw(r[0]), Fp::fromRaw(r[1]), Fp::fromRaw(r[2]), Fp::fromRaw(r[3]));
}
#else
#define EF_WSETUP
// smem_hip.py's LogUp alias words (gfx12 variant) when the WMMA staging is compiled out (EF_NO_WMMA)
__shared__ uint32_t ef_wlds[15u * EF_THREADS];
#endif
