__device__ const uint16_t rk_qb[] = {120,120,120,120,120,120,126,126,126,126,126,126,126,133,133,133,133,133,133,139,139,139,139,139,139,145,145,145,145,145,145,145,145,41,41,41,41,41,41,41,41,41,41,41,41,41,55,55,55,55,55,55,55,55,55,55,55,55,55,55,55,55,55,55,58,58,58,58,58,58,58,58,58,58,58,58,58,58,58,58,74,74,74,74,74,74,74,74,74,74,74,74,74,74,74,74,1,1,2,4,89,89,89,89,3,43,44,51,52};



// ---- eval_slab.py: per-row arrays live in a slot-major global slab (args[4]) ----
#ifndef RK_STRIDE
#define RK_STRIDE 1u
#endif
#define RK_NWORDS 304u
#ifdef EF_SLAB_ASM
__device__ __forceinline__ uint32_t ef_ldl(const void* p, uint32_t w) { uint32_t v; uint32_t a = (uint32_t)__cvta_generic_to_local(p) + 4u * w; asm volatile("ld.local.u32 %0, [%1];" : "=r"(v) : "r"(a)); return v; }
__device__ __forceinline__ void ef_stl(void* p, uint32_t w, uint32_t v) { uint32_t a = (uint32_t)__cvta_generic_to_local(p) + 4u * w; asm volatile("st.local.u32 [%0], %1;" :: "r"(a), "r"(v) : "memory"); }
#define RK_LD1(p, w) (static_cast<const ::risc0::Fp>(::risc0::Fp::fromRaw(ef_ldl((p), (w)))))
#define RK_ST1(p, w, v) ef_stl((p), (w), ::risc0::Fp(v).asRaw())
#else
#if defined(__HIP_DEVICE_COMPILE__)
// The slab is the kernel's private array (scratch_* rather than FLAT accesses).
typedef __attribute__((address_space(5))) uint32_t ef_pu32;
// Its address is the same in every lane: an SGPR address (ef_uptr).
__device__ __forceinline__ uint32_t ef_ldl(const void* p, uint32_t w) {
  return ((const ef_pu32*)(ef_uptr(p)))[(size_t)w * RK_STRIDE];
}
__device__ __forceinline__ void ef_stl(void* p, uint32_t w, uint32_t v) {
  ((ef_pu32*)(ef_uptr(p)))[(size_t)w * RK_STRIDE] = v;
}
#else
__device__ __forceinline__ uint32_t ef_ldl(const void* p, uint32_t w) {
  return reinterpret_cast<const uint32_t*>(p)[(size_t)w * RK_STRIDE];
}
__device__ __forceinline__ void ef_stl(void* p, uint32_t w, uint32_t v) {
  reinterpret_cast<uint32_t*>(p)[(size_t)w * RK_STRIDE] = v;
}
#endif
#define RK_LD1(p, w) (static_cast<const ::risc0::Fp>(::risc0::Fp::fromRaw(ef_ldl((p), (w)))))
#define RK_ST1(p, w, v) ef_stl((p), (w), ::risc0::Fp(v).asRaw())
#endif
#define RK_LD4(p, w0, w1, w2, w3) (static_cast<const ::risc0::FpExt>(::risc0::FpExt(RK_LD1(p, w0), RK_LD1(p, w1), RK_LD1(p, w2), RK_LD1(p, w3))))
#define RK_ST4(p, w0, w1, w2, w3, v) do { ::risc0::FpExt _rk_v = (v); RK_ST1(p, w0, _rk_v.elems[0]); RK_ST1(p, w1, _rk_v.elems[1]); RK_ST1(p, w2, _rk_v.elems[2]); RK_ST1(p, w3, _rk_v.elems[3]); } while (0)
// smem_hip.py: on gfx11 and gfx12 the hottest slab words of each phase in LDS (ef_sm), the rest in the
