static_assert(31u <= EF_NHOT + sizeof(ef_wlds) / sizeof(ef_wlds[0]) / EF_THREADS, "LogUp alias words");
#define EF_SMWL(k) ((k) < EF_NHOT ? ef_sm[(k) < EF_NHOT ? (k) : 0][threadIdx.x] : ef_wlds[((k) < EF_NHOT ? 0 : (k) - EF_NHOT) * EF_THREADS + threadIdx.x])
