#define RK_ST1L(p, w, v) do { if (ef_hotL(w) >= 0) EF_SMWL(ef_hotL(w) < 0 ? 0 : ef_hotL(w)) = ::risc0::Fp(v).asRaw(); else ef_stl((p), (w), ::risc0::Fp(v).asRaw()); } while (0)
#else // archsel_hip
__device__ __forceinline__ constexpr int ef_hotL(uint32_t w) { switch (w) { case 20u: return 0; case 21u: return 1; case 22u: return 2; case 23u: return 3; case 4u: return 4; case 5u: return 5; case 6u: return 6; case 7u: return 7; case 8u: return 8; case 9u: return 9; case 10u: return 10; case 11u: return 11; case 40u: return 12; case 41u: return 13; case 42u: return 14; case 43u: return 15; case 60u: return 16; case 61u: return 17; case 62u: return 18; case 63u: return 19; case 80u: return 20; case 81u: return 21; case 82u: return 22; case 83u: return 23; case 84u: return 24; case 85u: return 25; case 86u: return 26; case 87u: return 27; case 92u: return 28; case 93u: return 29; case 94u: return 30; case 95u: return 31; default: return -1; } }
