#define RK_ST1L(p, w, v) do { if (ef_hotL(w) >= 0) EF_SMW(ef_hotL(w) < 0 ? 0 : ef_hotL(w)) = ::risc0::Fp(v).asRaw(); else ef_stl((p), (w), ::risc0::Fp(v).asRaw()); } while (0)
#endif // archsel_hip
